def transfer_step(source: TransferStep | None = None) -> TransferStepBuilder:
    """A fresh TransferStepBuilder, optionally pre-loaded from an existing TransferStep."""
    made = TransferStepBuilder()
    return made.copy_base(source) if source is not None else made
